package dev.zomboid.decor;
import java.util.*;
import java.lang.reflect.Array;
public final class Storage {
 public static final Set<String> IDS=Set.of("acrate","acrate_2","acrate_3","knapsack","officedrawers_1","officedrawers_2","fridge","fridge_2","carton","carton_2","carton_3","plasticbox","plasticbox_2","plasticbox_3","plasticbox_4","goodsshelves","goodsshelves_2","goodsshelves_3","goodsshelves_4","goodsshelves_5","goodsshelves_6","vendingmachine","vendingmachine_2","vendingmachine_3","vendingmachine_4","insulationcabinet","indoorgarbagebin","woodencrate","weaponbox","toolbox","medicalbox","safe","luggage","redluggage","khakiluggage","blueluggage","greenluggage","greyluggage","blackluggage","ammunitionbox","mailbox_1","mailbox_2","metalcabinet","metalcabinet_2","metaldrawer","metaldrawer_2","shelf","shelf_2","shelf_3","shelf_4","weapon_rack","weapon_rack_2","weapon_rack_3","weapon_rack_4","woodencabinet","woodencabinet_2","woodendrawer","woodendrawer_2","cabinet","cabinet_2","cabinet_3","chemicalprotectiveclothing","chemicalprotectiveclothing_2","emptytesttuberack","testtuberack","testtuberack_2","testtuberack_3","testtuberack_4","testtuberack_5","accessorybox_1","accessorybox_2","desk","desk_2","desk_3","classroomdesk","officepartitiondesk","officepartitiondesk_2","officepartitiondesk_3","officepartitiondesk_4","officepartitiondesk_5","washingmachine","lockers","lockers_2","barrel","trashcan","trashcan_2","trashcan_3","trashcan_4","aircondition","aircondition_2","airconditioning","airconditioning_2","centralairconditioning","centralairconditioning_2");
 static final ThreadLocal<Object> SPEC=new ThreadLocal<>();
 public static String id(Object state){Object key=R.call(R.get(R.type("net.minecraft.core.registries.BuiltInRegistries"),"BLOCK"),"getKey",R.call(state,"getBlock"));return key.toString().replace("doomsday_decoration:","");}
 public static void before(Object spec){SPEC.set(spec);}
 public static void configure(Object spec,Object props){before(spec);Footprint.spec(spec);if(IDS.contains(R.get(spec,"id"))||Footprint.IDS.contains(R.get(spec,"id")))R.call(props,"pushReaction",R.get(R.type("net.minecraft.world.level.material.PushReaction"),"BLOCK"));}
 public static void properties(Object builder){Object s=SPEC.get();if(s==null)throw new IllegalStateException("No furniture spec");List<Object> props=new ArrayList<>();Class<?> b=R.type("net.mcreator.doomsdaydecoration.port.PortedBlock");if(R.yes(R.get(s,"axis")))props.add(R.get(b,"AXIS"));if(R.yes(R.get(s,"directional_facing")))props.add(R.get(b,"FULL_FACING"));else if(R.yes(R.get(s,"facing")))props.add(R.get(b,"FACING"));if(R.yes(R.get(s,"attach_face")))props.add(R.get(b,"FACE"));if(R.yes(R.get(s,"waterlogged")))props.add(R.get(b,"WATERLOGGED"));Object a=Array.newInstance(R.type("net.minecraft.world.level.block.state.properties.Property"),props.size());for(int i=0;i<props.size();i++)Array.set(a,i,props.get(i));R.call(builder,"add",a);}
 public static Object validBlocks(Map<?,?> map){List<Object> blocks=new ArrayList<>();for(String id:IDS)blocks.add(R.call(map.get(id),"get"));if(Footprint.PART==null)throw new IllegalStateException("Furniture part not registered");blocks.add(Footprint.PART);Object a=Array.newInstance(R.type("net.minecraft.world.level.block.Block"),blocks.size());for(int i=0;i<blocks.size();i++)Array.set(a,i,blocks.get(i));return a;}
 public static int rows(String id){if(id.equals("acrate")||id.contains("mailbox")||id.contains("testtube")||id.startsWith("accessorybox"))return 1;if(id.contains("luggage")||id.equals("knapsack")||id.startsWith("carton")||id.equals("medicalbox")||id.equals("toolbox")||id.equals("ammunitionbox"))return 2;if(id.startsWith("lockers"))return 6;if(id.startsWith("goodsshelves")||id.equals("safe")||id.startsWith("cabinet")||id.startsWith("shelf"))return 6;if(id.contains("cabinet")||id.contains("fridge")||id.equals("weaponbox")||id.startsWith("weapon_rack"))return 4;return 3;}
 public static int size(Object be){return rows(id(R.call(be,"getBlockState")))*9;}
 public static Object empty(Object be){return R.call(R.type("net.minecraft.core.NonNullList"),"withSize",size(be),R.get(R.type("net.minecraft.world.item.ItemStack"),"EMPTY"));}
 public static Object title(Object be){return R.call(R.type("net.minecraft.network.chat.Component"),"translatable",R.call(R.call(R.call(be,"getBlockState"),"getBlock"),"getDescriptionId"));}
 public static Object menu(Object be,int n,Object inventory){int rows=size(be)/9;Object type=R.get(R.type("net.minecraft.world.inventory.MenuType"),"GENERIC_9x"+rows);return R.make("net.minecraft.world.inventory.ChestMenu",type,n,inventory,be,rows);}
 public static int[] slots(Object be){return R.yes(R.get(be,"ddPart"))||Climate.air(id(R.call(be,"getBlockState")))?new int[0]:java.util.stream.IntStream.range(0,size(be)).toArray();}
 public static Object provider(Object world,Object pos){if(Climate.air(id(R.call(world,"getBlockState",pos))))return null;repair(world,pos);String id=id(R.call(world,"getBlockState",pos));if(!IDS.contains(id)&&!id.equals("interaction_part"))return null;Object be=R.call(world,"getBlockEntity",pos);if(be==null)return null;Object root=Footprint.root(be);return root==null?(be.getClass().getName().endsWith("AcrateBlockEntity")&&R.yes(R.get(be,"ddPart"))?null:be):R.call(world,"getBlockEntity",root);}
 public static void save(Object be,Object tag){R.call(tag,"putLong","DDRoot",R.get(be,"ddRoot"));R.call(tag,"putBoolean","DDPart",R.get(be,"ddPart"));R.call(tag,"putString","DDOwner",R.get(be,"ddOwner"));R.call(tag,"putInt","DDIce",R.get(be,"ddIce"));R.call(tag,"putInt","DDChill",R.get(be,"ddChill"));}
 public static void load(Object be,Object tag){R.set(be,"ddRoot",R.call(tag,"getLong","DDRoot"));R.set(be,"ddPart",R.call(tag,"getBoolean","DDPart"));R.set(be,"ddOwner",R.call(tag,"getString","DDOwner"));R.set(be,"ddIce",R.call(tag,"getInt","DDIce"));R.set(be,"ddChill",R.call(tag,"getInt","DDChill"));}
 public static Object sync(Object be){Object tag=R.make("net.minecraft.nbt.CompoundTag");save(be,tag);return tag;}
 public static Object packet(Object be){return R.call(R.type("net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket"),"create",be);}
 public static boolean removed(Object state,Object world,Object pos,Object next){if(R.call(state,"getBlock")==R.call(next,"getBlock"))return false;return Footprint.remove(state,world,pos);}
 public static void placed(Object world,Object pos,Object state){repair(world,pos);Footprint.ensure(world,pos,state);}
 public static Object render(Object state){return R.get(R.type("net.minecraft.world.level.block.RenderShape"),id(state).equals("interaction_part")?"INVISIBLE":"MODEL");}
 public static void repair(Object world,Object pos){if(R.yes(R.call(world,"isClientSide"))||!R.yes(R.call(world,"hasChunkAt",pos)))return;Object state=R.call(world,"getBlockState",pos);if(!IDS.contains(id(state))||R.call(world,"getBlockEntity",pos)!=null)return;Object block=R.call(state,"getBlock");if(!R.type("net.minecraft.world.level.block.EntityBlock").isInstance(block))return;Object be=R.call(block,"newBlockEntity",pos,state);if(be!=null){R.call(world,"setBlockEntity",be);R.call(be,"setChanged");R.call(world,"sendBlockUpdated",pos,state,state,3);}}
 public static Object use(Object state,Object world,Object pos,Object player,Object hit){repair(world,pos);if(Climate.air(id(state))){Climate.use(world,pos,player);return R.call(R.type("net.minecraft.world.InteractionResult"),"sidedSuccess",R.call(world,"isClientSide"));}Object partBe=R.call(world,"getBlockEntity",pos),root=partBe==null?null:Footprint.root(partBe);if(root!=null){Object rootState=R.call(world,"getBlockState",root);return R.call(R.call(rootState,"getBlock"),"useWithoutItem",rootState,world,root,player,R.call(hit,"withPosition",root));}Footprint.ensure(world,pos,state);if(!R.yes(R.call(world,"isClientSide"))){Object provider=provider(world,pos);if(provider!=null)R.call(player,"openMenu",provider);}return R.call(R.type("net.minecraft.world.InteractionResult"),"sidedSuccess",R.call(world,"isClientSide"));}
}
